button { border: none; border-radius: 6px; padding: 10px 16px; background: #234f98; color: white; font: inherit; cursor: pointer; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #c77d00; outline-offset: 3px; }
[role="alert"] { color: #a02020; }
[role="alert"]:empty { display: none; }
ul { list-style: none; padding: 0; margin: 24px 0 0; }
li { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 0; border-top: 1px solid #dce3ed; }
li span { overflow-wrap: anywhere; }
li button { flex-shrink: 0; }
@media (max-width: 600px) { main { margin: 16px; padding: 20px; } }

