    await server.stop();
    server = undefined;
    server = await start(databasePath);
    assert.deepEqual(await (await request(tasksPath)).json(), expected);
    assert.deepEqual(await (await request(otherPath)).json(), []);
    assert.equal((await request(`/projects/${first.id}`)).status, 200);
